      "标题": "贈衛八處士",
      "上句": "人生不相見",
      "下句": "人生不相見，\n動如參與商。\n今夕復何夕？\n共此燈燭光。\n少壯能幾時？\n鬢髮各已蒼。\n訪舊半為鬼，\n驚呼熱中腸。\n焉知二十載，\n重上君子堂。\n昔別君未婚，\n兒女忽成行；\n怡然敬父執，\n問我來何方？\n問答乃未已，\n驅兒羅酒漿。\n夜雨剪春韭，\n新炊間黃梁。\n主稱會面難，\n一舉累十觴；\n十觴亦不醉，\n感子故意長。\n明日隔山岳，\n世事兩茫茫。",
