      "原文": "絕代有佳人，\n幽居在空谷。\n自云良家子，\n零落依草木。\n關中昔喪亂，\n兄弟遭殺戮；\n官高何足論，\n不得收骨肉。\n世情惡衰歇，\n萬事隨轉燭。\n夫婿輕薄兒，\n新人美如玉。\n合昏尚知時，\n鴛鴦不獨宿；\n但見新人笑，\n那聞舊人哭？\n在山泉水清，\n出山泉水濁。\n侍婢賣珠迴，\n牽蘿補茅屋。\n摘花不插髮，\n采柏動盈掬。\n天寒翠袖薄，\n日暮倚修竹。",
      "译文": "",
      "注释": "",
      "赏析": "咏战乱中幽居空谷的佳人，以「在山泉水清」自守高洁，寄寓诗人身世之感。笔致顿挫，怨而不怒。",
