    "fields": {
      "篇目": "唐诗三百首 · 五言古诗 · 杜甫 · 夢李白（二首之一）",
      "标题": "夢李白（二首之一）",
      "上句": "死別已吞聲",
      "下句": "死別已吞聲，\n生別常惻惻。\n江南瘴癘地，\n逐客無消息；\n故人入我夢，\n明我長相憶。\n君今在羅網，\n何以有羽翼？\n恐非平生魂，\n路遠不可測。\n魂來楓林青，\n魂返關山黑；\n落月滿屋梁，\n猶疑照顏色。\n水深波浪闊，\n無使蛟龍得。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
