      "上句": "",
      "下句": "",
      "原文": "下馬飲君酒，\n問君何所之？\n君言不得意，\n歸臥南山陲。\n但去莫復問，\n白雲無盡時。",
      "译文": "",
      "注释": "",
      "赏析": "山间送别，言「問君何所之」而答以归山，末「但去莫復問，白雲無盡時」见超然之致。寥寥数语，意境空远。",
