      "上句": "言入黃花川",
      "下句": "言入黃花川，\n每逐青谿水；\n隨山將萬轉，\n趣途無百里。\n聲喧亂石中，\n色靜深松裡；\n漾漾汎菱荇，\n澄澄映葭葦。\n我心素已閒，\n清川澹如此。\n請留盤石上，\n垂釣將已矣。",
