      "上句": "斜光照墟落",
      "下句": "斜光照墟落，\n窮巷牛羊歸。\n野老念牧童，\n倚杖候荊扉。\n雉雊麥苗秀，\n蠶眠桑葉稀。\n田夫荷鋤立，\n相見語依依。\n即此羨閒逸，\n悵然吟式微。",
