      "篇目": "唐诗三百首 · 五言古诗 · 王維 · 西施詠",
      "标题": "西施詠",
      "上句": "艷色天下重",
      "下句": "艷色天下重，\n西施寧久微？\n朝為越溪女，\n暮作吳宮妃。\n賤日豈殊眾？\n貴來方悟稀。\n邀人傅脂粉，\n不自著羅衣。\n君寵益嬌態，\n君憐無是非。\n當時浣紗伴，\n莫得同車歸。\n持謝鄰家子，\n效顰安可希？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
