      "上句": "北山白雲裡",
      "下句": "北山白雲裡，\n隱者自怡悅。\n相望始登高，\n心隨雁飛滅。\n愁因薄暮起，\n興是清秋發。\n時見歸村人，\n沙行渡頭歇。\n天邊樹若薺，\n江畔洲如月。\n何當載酒來？\n共醉重陽節。",
