      "上句": "山光忽西落",
      "下句": "山光忽西落，\n池月漸東上。\n散髮乘夜涼，\n開軒臥閑敞。\n荷風送香氣，\n竹露滴清響。\n欲取鳴琴彈，\n恨無知音賞！\n感此懷故人，\n中宵勞夢想。",
      "原文": "",
