      "上句": "",
      "下句": "",
      "原文": "山光忽西落，\n池月漸東上。\n散髮乘夜涼，\n開軒臥閑敞。\n荷風送香氣，\n竹露滴清響。\n欲取鳴琴彈，\n恨無知音賞！\n感此懷故人，\n中宵勞夢想。",
      "译文": "",
      "注释": "",
      "赏析": "夏夜纳凉怀友，从日落写到月出，「荷風送香氣，竹露滴清響」写景入微。末盼友不至，怅然之情自然流出。",
