      "原文": "高臥南齋時，\n開帷月初吐；\n清輝淡水木，\n演漾在窗戶。\n苒苒幾盈虛？\n澄澄變今古。\n美人清江畔，\n是夜越吟苦。\n千里其如何？\n微風吹蘭杜。",
