      "上句": "幽意無斷絕",
      "下句": "幽意無斷絕，\n此去隨所偶。\n晚風吹行舟，\n花路入溪口。\n際夜轉西壑，\n隔山望南斗。\n潭煙飛溶溶，\n林月低向後。\n生事且瀰漫，\n願為持竿叟。",
