      "上句": "",
      "下句": "",
      "原文": "幽意無斷絕，\n此去隨所偶。\n晚風吹行舟，\n花路入溪口。\n際夜轉西壑，\n隔山望南斗。\n潭煙飛溶溶，\n林月低向後。\n生事且瀰漫，\n願為持竿叟。",
      "译文": "",
      "注释": "",
      "赏析": "春夜泛舟若耶溪，随流任情，「晚風吹行舟，花路入溪口」清丽如画。全篇以「幽意」贯之，淡雅宜人。",
