      "上句": "",
      "下句": "",
      "原文": "清溪深不測，\n隱處唯孤雲。\n松際露微月，\n清光猶為君。\n茅亭宿花影，\n藥院滋苔紋。\n余亦謝時去，\n西山鸞鶴群。",
