      "原文": "兵衛森畫戟，\n宴寢凝清香。\n海上風雨至，\n逍遙池閣涼。\n煩痾近消散，\n嘉賓復滿堂。\n自慚居處崇，\n未睹斯民康。\n理會是非遣，\n性達形跡忘。\n鮮肥屬時禁，\n蔬果幸見嘗。\n俯飲一杯酒，\n仰聆金玉章。\n神歡體自輕，\n意欲淩風翔。\n吳中盛文史，\n群彥今汪洋。\n方知大藩地，\n豈曰財賦強？",
      "译文": "",
