      "上句": "",
      "下句": "",
      "原文": "今朝郡齋冷，\n忽念山中客；\n澗底束荊薪，\n歸來煮白石。\n欲持一瓢酒，\n遠慰風雨夕。\n落葉滿空山，\n何處尋行跡？",
      "译文": "",
      "注释": "",
      "赏析": "寒斋寄怀山中道士，想其采药云山、饥食空山，末「遙看一片雲」见神交之趣。萧疏淡远，冷峭有味。",
