      "原文": "落帆逗淮鎮，\n停舫臨孤驛。\n浩浩風起波，\n冥冥日沈夕。\n人歸山郭暗，\n雁下蘆洲白。\n獨夜憶秦關，\n聽鐘未眠客。",
