      "标题": "東郊",
      "上句": "",
      "下句": "",
      "原文": "吏舍跼終年，\n出郊曠清曙。\n楊柳散和風，\n青山澹吾慮。\n依叢適自憩，\n緣澗還復去。\n微雨靄芳原，\n春鳩鳴何處？\n樂幽心屢止，\n遵事跡猶遽。\n終罷斯結廬，\n慕陶真可庶。",
      "译文": "",
      "注释": "",
      "赏析": "久居吏舍而乐东郊之游，「微雨靄芳原」写郊野清景，末「即事玩文墨」见自适之趣。清丽闲雅。",
      "链接": ""
