      "标题": "送楊氏女",
      "上句": "",
      "下句": "",
      "原文": "永日方慼慼，\n出行復悠悠。\n女子今有行，\n大江泝輕舟。\n爾輩苦無恃，\n撫念益慈柔。\n幼為長所育，\n兩別泣不休。\n對此結中腸，\n義往難復留。\n自小闕內訓，\n事姑貽我憂。\n賴茲託令門，\n仁卹庶無尤。\n貧儉誠所尚，\n資從豈待周！\n孝恭遵婦道，\n容止順其猷。\n別離在今晨，\n見爾當何秋？\n居閑始自遣，\n臨感忽難收。\n歸來視幼女，\n零淚緣纓流。",
      "译文": "",
