      "原文": "汲井漱寒齒，\n清心拂塵服。\n閒持貝葉書，\n步出東齋讀。\n真源了無取，\n妄跡世所逐。\n遺言冀可冥，\n繕性何由熟？\n道人庭宇靜，\n苔色連深竹；\n日出霧露餘，\n青松如膏沐。\n澹然離言說，\n悟悅心自足。",
