      "标题": "關山月",
      "上句": "明月出天山",
      "下句": "明月出天山，\n蒼茫雲海間；\n長風幾萬里，\n吹度玉門關。\n漢下白登道，\n胡窺青海灣。\n由來征戰地，\n不見有人還。\n戍客望邊色，\n思歸多苦顏；\n高樓當此夜，\n歎息未應閑。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
