      "标题": "長干行",
      "上句": "",
      "下句": "",
      "原文": "妾髮初覆額，\n折花門前劇；\n郎騎竹馬來，\n遶床弄青梅。\n同居長干里，\n兩小無嫌猜。\n十四為君婦，\n羞顏未嘗開；\n低頭向暗壁，\n千喚不一回。\n十五始展眉，\n願同塵與灰；\n常存抱柱信，\n豈上望夫臺？\n十六君遠行，\n瞿塘灩澦堆；\n五月不可觸，\n猿鳴天上哀。\n門前遲行跡，\n一一生綠苔；\n苔深不能掃，\n落葉秋風早。\n八月蝴蝶來，\n雙飛西園草。\n感此傷妾心，\n坐愁紅顏老。\n早晚下三巴，\n預將書報家；\n相迎不道遠，\n直至長風沙。",
      "译文": "",
      "注释": "",
      "赏析": "以女子口吻自述与夫自幼相识、两小无猜以至长别相思的往事，末「直至長風沙」见盼归之切。叙事缠绵，情致深婉。",
