      "原文": "男兒事長征，\n少小幽燕客，\n賭勝馬蹄下，\n由來輕七尺。\n殺人莫敢前，\n鬚如蝟毛磔。\n黃雲隴底白雲飛，\n未得報恩不能歸。\n遼東小婦年十五，\n慣彈琵琶解歌舞，\n今為羌笛出塞聲，\n使我三軍淚如雨。",
