      "原文": "四月南風大麥黃，\n棗花未落桐葉長。\n青山朝別暮還見，\n嘶馬出門思故鄉。\n陳侯立身何坦蕩？\n虯鬚虎眉仍大顙。\n腹中貯書一萬卷，\n不肯低頭在草莽。\n東門酤酒飲我曹，\n心輕萬事皆鴻毛；\n醉臥不知白日暮，\n有時空望孤雲高。\n長河浪頭連天黑，\n津吏停舟渡不得。\n鄭國遊人未及家，\n洛陽行子空嘆息！\n聞道故林相識多，\n罷官昨日今如何？",
      "译文": "",
      "注释": "",
      "赏析": "送别友人，从四月南风写到醉卧席前，末「聞道故林相識多」宽慰中有依依之情。豪宕洒脱，情真意切。",
