      "标题": "琴歌",
      "上句": "主人有酒歡今夕",
      "下句": "主人有酒歡今夕，\n請奏鳴琴廣陵客。\n月照城頭烏半飛，\n霜淒萬樹風入衣。\n銅鑪華燭燭增輝，\n初彈淥水後楚妃。\n一聲已動物皆靜，\n四座無言星欲稀。\n清淮奉使千餘里，\n敢告雲山從此始。",
      "原文": "",
      "译文": "",
      "注释": "",
