      "原文": "蔡女昔造胡笳聲，\n一彈一十有八拍。\n胡人落淚沾邊草，\n漢使斷腸對歸客。\n古戍蒼蒼烽火寒，\n大荒沈沈飛雪白。\n先拂商絃後角羽，\n四郊秋葉驚摵摵。\n董夫子，通神明，\n深山竊聽來妖精。\n言遲更速皆應手，\n將往復旋如有情。\n空山百鳥散還合，\n萬里浮雲陰且晴。\n嘶酸雛雁失群夜，\n斷絕胡兒戀母聲。\n川為靜其波，\n鳥亦罷其鳴。\n烏珠部落家鄉遠，\n邏娑沙塵哀怨生。\n幽音變調忽飄灑，\n長風吹林雨墮瓦；\n迸泉颯颯飛木末，\n野鹿呦呦走堂下。\n長安城連東掖垣，\n鳳凰池對青瑣門，\n高才脫略名與利，\n日夕望君抱琴至。",
