      "下句": "山寺鐘鳴晝已昏，\n漁梁渡頭爭渡喧；\n人隨沙路向江村，\n余亦乘舟歸鹿門。\n鹿門月照開煙樹，\n忽到龐公棲隱處；\n岩扉松徑長寂寥，\n惟有幽人自來去。",
