      "标题": "廬山謠寄盧侍御虛舟",
      "上句": "我本楚狂人",
      "下句": "我本楚狂人，\n鳳歌笑孔丘。\n手持綠玉杖，\n朝別黃鶴樓，\n五岳尋仙不辭遠，\n一生好入名山遊。\n廬山秀出南斗傍，\n屏風九疊雲錦張；\n影落明湖青黛光，\n金闕前開二峰長。\n銀河倒挂三石梁，\n香爐瀑布遙相望。\n迴崖沓障淩蒼蒼，\n翠影紅霞映朝日，\n鳥飛不到吳天長。\n登高壯觀天地間，\n大江茫茫去不還。\n黃雲萬里動風色，\n白波九道流雪山。\n好為廬山謠，\n興因廬山發。\n閑窺石鏡清我心，\n謝公行處蒼苔沒。\n早服還丹無世情，\n琴心三疊道初成。\n遙見仙人彩雲裡，\n手把芙蓉朝玉京。\n先期汗漫九垓上，\n願接盧敖遊太清。",
