      "标题": "宣州謝朓樓餞別校書叔雲",
      "上句": "棄我去者",
      "下句": "棄我去者，\n昨日之日不可留；\n亂我心者，\n今日之日多煩憂。\n長風萬里送秋雁，\n對此可以酣高樓。\n蓬萊文章建安骨，\n中間小謝又清發。\n俱懷逸興壯思飛，\n欲上青天覽明月。\n抽刀斷水水更流，\n舉杯銷愁愁更愁。\n人生在世不稱意，\n明朝散髮弄扁舟。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
