      "下句": "君不見走馬川行雪海邊，\n平沙莽莽黃入天。\n輪臺九月風夜吼，\n一川碎石大如斗，\n隨風滿地石亂走。\n匈奴草黃馬正肥，\n金山西見煙塵飛，\n漢家大將西出師。\n將軍金甲夜不脫，\n半夜軍行戈相撥，\n風頭如刀面如割。\n馬毛帶雪汗氣蒸，\n五花連錢旋作冰，\n幕中草檄硯水凝。\n虜騎聞之應膽懾，\n料知短兵不敢接，\n車師西門佇獻捷。",
