      "标题": "白雪歌送武判官歸",
      "上句": "北風捲地白草折",
      "下句": "北風捲地白草折，\n胡天八月即飛雪；\n忽如一夜春風來，\n千樹萬樹梨花開。\n散入珠簾濕羅幕，\n狐裘不煖錦衾薄；\n將軍角弓不得控，\n都護鐵衣冷猶著。\n瀚海闌干百丈冰，\n愁雲黲淡萬里凝。\n中軍置酒飲歸客，\n胡琴琵琶與羌笛。\n紛紛暮雪下轅門，\n風掣紅旗凍不翻。\n輪臺東門送君去，\n去時雪滿天山路；\n山迴路轉不見君，\n雪上空留馬行處。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
