      "原文": "今我不樂思岳陽，\n身欲奮飛病在床；\n美人娟娟隔秋水，\n濯足洞庭望八荒。\n鴻飛冥冥日月白，\n青楓葉赤天雨霜。\n玉京群帝集北斗，\n或騎麒麟翳鳳凰。\n芙蓉旌旗煙霧落，\n影動倒景搖瀟湘。\n星宮之君醉瓊漿，\n羽人稀少不在旁。\n似聞昨者赤松子，\n恐是漢代韓張良；\n昔隨劉氏定長安，\n帷幄未改神慘傷。\n國家成敗吾豈敢？\n色難腥腐餐楓香。\n周南留滯古所惜，\n南極老人應壽昌。\n美人胡為隔秋水？\n焉得置之貢玉堂！",
