      "篇目": "唐诗三百首 · 七言古诗 · 杜甫 · 古柏行",
      "标题": "古柏行",
      "上句": "孔明廟前有老柏",
      "下句": "孔明廟前有老柏，\n柯如青銅根如石；\n霜皮溜雨四十圍，\n黛色參天二千尺。\n君臣已與時際會，\n樹木猶為人愛惜；\n雲來氣接巫峽長，\n月出寒通雪山白。\n憶昨路繞錦亭東，\n先主武侯同閟宮；\n崔嵬枝幹郊原古，\n窈窕丹青戶牖空。\n落落盤踞雖得地，\n冥冥孤高多烈風；\n扶持自是神明力，\n正直元因造化功。\n大廈如傾要梁棟，\n萬牛迴首丘山重；\n不露文章世已驚，\n未辭剪伐誰能送。\n苦心豈免容螻蟻，\n香葉終經宿鸞鳳；\n志士幽人莫怨嗟，\n古來材大難為用！",
