      "篇目": "唐诗三百首 · 七言古诗 · 杜甫 · 觀公孫大娘弟子舞劍器行",
      "标题": "觀公孫大娘弟子舞劍器行",
      "上句": "昔有佳人公孫氏",
      "下句": "昔有佳人公孫氏，\n一舞劍器動四方；\n觀者如山色沮喪，\n天地為之久低昂。\n霍如羿射九日落，\n矯如群帝驂龍翔；\n來如雷霆收震怒，\n罷如江海凝清光。\n絳唇珠袖兩寂寞，\n晚有弟子傳芬芳。\n臨潁美人在白帝，\n妙舞此曲神揚揚。\n與余問答既有以，\n感時撫事增惋傷。\n先帝侍女八千人，\n公孫劍器初第一。\n五十年間似反掌，\n風塵澒洞昏王室。\n梨園子弟散如煙，\n女樂餘姿映寒日。\n金粟堆前木已拱，\n瞿塘石城草蕭瑟。\n玳筵急管曲復終，\n樂極哀來月東出。\n老夫不知其所往？\n足繭荒山轉愁疾。",
