      "上句": "石魚湖，似洞庭",
      "下句": "石魚湖，似洞庭，\n夏水欲滿君山青。\n山為樽，水為沼，\n酒徒歷歷坐洲島。\n長風連日作大浪，\n不能廢人運酒舫。\n我持長瓢坐巴邱，\n酌飲四座以散愁。",
