      "原文": "山石犖确行徑微，\n黃昏到寺蝙蝠飛。\n升堂坐階新雨足，\n芭蕉葉大梔子肥。\n僧言古壁佛畫好，\n以火來照所見稀。\n鋪床拂席置羹飯，\n疏糲亦足飽我飢。\n夜深靜臥百蟲絕，\n清月出嶺光入扉。\n天明獨去無道路，\n出入高下窮煙霏。\n山紅澗碧紛爛漫，\n時見松櫪皆十圍。\n當流赤足蹋澗石，\n水聲激激風吹衣。\n人生如此自可樂，\n豈必局束為人鞿？\n嗟哉吾黨二三子，\n安得至老不更歸？",
