    "fields": {
      "篇目": "唐诗三百首 · 七言古诗 · 韓愈 · 八月十五夜贈張功曹",
      "标题": "八月十五夜贈張功曹",
      "上句": "纖雲四捲天無河",
      "下句": "纖雲四捲天無河，\n清風吹空月舒波。\n沙平水息聲影絕，\n一杯相屬君當歌。\n君歌聲酸辭且苦，\n不能聽終淚如雨。\n洞庭連天九疑高，\n蛟龍出沒猩鼯號。\n十生九死到官所，\n幽居默默如藏逃。\n下床畏蛇食畏藥，\n海氣濕蟄熏腥臊。\n昨者州前槌大鼓，\n嗣皇繼聖登夔皋。\n赦書一日行萬里，\n罪從大辟皆除死；\n遷者追回流者還，\n滌瑕蕩垢清朝班。\n州家申名使家抑，\n坎軻祇得移荊蠻。\n判司卑官不堪說，\n未免捶楚塵埃間。\n同時輩流多上道，\n天路幽險難追攀。\n君歌且休聽我歌，\n我歌今與君殊科。\n一年明月今宵多，\n人生由命非由他，\n有酒不飲奈明何？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
