      "标题": "謁衡岳廟遂宿嶽寺題門樓",
      "上句": "",
      "下句": "",
      "原文": "五嶽祭秩皆三公，\n四方環鎮嵩當中。\n火維地荒足妖怪，\n天假神柄專其雄。\n噴雲泄霧藏半腹，\n雖有絕頂誰能窮？\n我來正逢秋雨節，\n陰氣晦昧無清風。\n潛心默禱若有應，\n豈非正直能感通？\n須臾靜掃眾峰出，\n仰見突兀撐青空。\n紫蓋連延接天柱，\n石廩騰擲堆祝融。\n森然魄動下馬拜，\n松柏一逕趨靈宮。\n紛牆丹柱動光彩，\n鬼物圖畫填青紅。\n升階傴僂薦脯酒，\n欲以菲薄明其衷。\n廟內老人識神意，\n睢盱偵伺能鞠躬。\n手持盃珓導我擲，\n云此最吉餘難同。\n竄逐蠻荒幸不死，\n衣食纔足甘長終。\n侯王將相望久絕，\n神縱欲福難為功。\n夜投佛寺上高閣，\n星月掩映雲曈曨。\n猿鳴鐘動不知曙，\n杲杲寒日生於東。",
      "译文": "",
      "注释": "",
      "赏析": "谒衡岳庙而写其灵异，「雲開衡岳積陰晴」见气象之变，末「神縱欲福難為功」见旷达。奇崛雄浑。",
