      "篇目": "唐诗三百首 · 七言古诗 · 柳宗元 · 漁翁",
      "标题": "漁翁",
      "上句": "漁翁夜傍西巖宿",
      "下句": "漁翁夜傍西巖宿，\n曉汲清湘然楚竹。\n煙銷日出不見人，\n欸乃一聲山水綠。\n迴看天際下中流，\n巖上無心雲相逐。",
