    "fields": {
      "篇目": "唐诗三百首 · 七言古诗 · 李商隱 · 韓碑",
      "标题": "韓碑",
      "上句": "元和天子神武姿",
      "下句": "元和天子神武姿，\n彼何人哉軒與羲。\n誓將上雪列聖恥，\n坐法宮中朝四夷。\n淮西有賊五十載，\n封狼生貙貙生羆。\n不據山河據平地，\n長戈利矛日可麾。\n帝得聖相相曰度，\n賊斫不死神扶持，\n腰懸相印作都統，\n陰風慘澹天王旗。\n愬武古通作牙爪，\n儀曹外郎載筆隨；\n行軍司馬智且勇，\n十四萬眾猶虎貔。\n入蔡縛賊獻太廟，\n功無與讓恩不訾。\n帝曰汝度功第一，\n汝從事愈宜為辭。\n愈拜稽首蹈且舞：\n金石刻畫臣能為，\n古者世稱大手筆；\n此事不係於職司。\n當仁自古有不讓，\n言訖屢頷天子頤。\n公退齋戒坐小閣，\n濡染大筆何淋漓。\n點竄堯典舜典字，\n塗改清廟生民詩。\n文成破體書在紙，\n清晨再拜鋪丹墀。\n表曰臣愈昧死上，\n詠神聖功書之碑。\n碑高三丈字如斗，\n負以靈鼇蟠以螭。\n句奇語重喻者少，\n讒之天子言其私。\n長繩百尺拽碑倒，\n麤沙大石相磨治。\n公之斯文若元氣，\n先時已入人肝脾；\n湯盤孔鼎有述作，\n今無其器存其辭。\n嗚呼聖皇及聖相，\n相與烜赫流淳熙。\n公之斯文不示後，\n曷與三五相攀追？\n願書萬本誦萬過，\n口角流沫右手胝；\n傳之七十有二代，\n以為封禪玉檢明堂基。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
