      "原文": "漢家煙塵在東北，\n漢將辭家破殘賊。\n男兒本自重橫行，\n天子非常賜顏色。\n摐金伐鼓下榆關，\n旌旆逶迤碣石間。\n校尉羽書飛瀚海，\n單于獵火照狼山。\n山川蕭條極邊土，\n胡騎憑陵雜風雨。\n戰士軍前半死生，\n美人帳下猶歌舞。\n大漠窮秋塞草衰，\n孤城落日鬥兵稀。\n身當恩遇常輕敵，\n力盡關山未解圍。\n鐵衣遠戍辛勤久，\n玉筋應啼別離後；\n少婦城南欲斷腸，\n征人薊北空回首。\n邊庭飄颻那可度？\n絕域蒼茫更何有。\n殺氣三時作陣雲，\n寒聲一夜傳刁斗。\n相看白刃血紛紛，\n死節從來豈顧勳？\n君不見沙場征戰苦？\n至今猶憶李將軍。",
