      "上句": "白日登山望烽火",
      "下句": "白日登山望烽火，\n黃昏飲馬傍交河。\n行人刁斗風沙暗，\n公主琵琶幽怨多。\n野雲萬里無城郭，\n雨雪紛紛連大漠。\n胡雁哀鳴夜夜飛，\n胡兒眼淚雙雙落。\n聞道玉門猶被遮，\n應將性命逐輕車。\n年年戰骨埋荒外，\n空見葡萄入漢家。",
