      "原文": "洛陽女兒對門居，\n纔可容顏十五餘。\n良人玉勒乘驄馬，\n侍女金盤膾鯉魚。\n畫閣朱樓盡相望，\n紅桃綠柳垂簷向。\n羅帷送上七香車，\n寶扇迎歸九華帳。\n狂夫富貴在青春，\n意氣驕奢劇季倫。\n自憐碧玉親教舞，\n不惜珊瑚持與人。\n春窗曙滅九微火，\n九微片片飛花璅。\n戲罷曾無理曲時，\n妝成祇是薰香坐。\n城中相識盡繁華，\n日夜經過趙李家。\n誰憐越女顏如玉，\n貧賤江頭自浣紗。",
