      "原文": "噫吁戲！\n危乎高哉！\n蜀道之難難於上青天。\n蠶叢及魚鳧，\n開國何茫然。\n爾來四萬八千歲，\n始與秦塞通人煙。\n西當太白有鳥道，\n可以橫絕峨嵋巔。\n地崩山摧壯士死，\n然後天梯石棧相鉤連。\n上有六龍回日之高標，\n下有衝波逆折之迴川。\n黃鶴之飛尚不得，\n猿猱欲度愁攀援。\n青泥何盤盤，\n百步九折縈巖巒。\n捫參歷井仰脅息，\n以手撫膺坐長歎。\n問君西遊何時還？\n畏途巉岩不可攀。\n但見悲鳥號古木，\n雄飛雌從繞林間；\n又聞子規啼夜月，\n愁空山。\n蜀道之難難於上青天，\n使人聽此凋朱顏。\n連峰去天不盈尺，\n枯松倒掛倚絕壁。\n飛湍瀑流爭喧豗，\n砯崖轉石萬壑雷。\n其險也如此！\n嗟爾遠道之人，\n胡為乎來哉？\n劍閣崢嶸而崔嵬，\n一夫當關，\n萬夫莫開。\n所守或匪親，\n化為狼與豺。\n朝避猛虎，\n夕避長蛇。\n磨牙吮血，\n殺人如麻。\n錦城雖云樂，\n不如早還家！\n蜀道之難難於上青天，\n側身西望常咨嗟！",
      "译文": "",
      "注释": "",
      "赏析": "以「噫吁嚱」发端写蜀道之险，末「錦城雖云樂，不如早還家」见规劝之意。想象奇绝，气势磅礴，为李白代表作。",
