      "原文": "長相思，\n在長安。\n絡緯秋啼金井闌，\n微霜淒淒簟色寒。\n孤燈不明思欲絕，\n卷帷望月空長歎！\n美人如花隔雲端。\n上有青冥之長天，\n下有淥水之波瀾。\n天長路遠魂飛苦，\n夢魂不到關山難。\n長相思，\n摧心肝！",
