      "篇目": "唐诗三百首 · 杂言古诗 · 李白 · 長相思（二首之二）",
      "标题": "長相思（二首之二）",
      "上句": "日色已盡花含煙",
      "下句": "日色已盡花含煙，\n月明欲素愁不眠。\n趙瑟初停鳳凰柱，\n蜀琴欲奏鴛鴦絃。\n此曲有意無人傳，\n願隨春風寄燕然。\n憶君迢迢隔青天。\n昔日橫波目，\n今成流淚泉。\n不信妾腸斷，\n歸來看取明鏡前！",
      "原文": "",
      "译文": "",
