      "原文": "金樽清酒斗十千，\n玉盤珍饈值萬錢。\n停杯投箸不能食，\n拔劍四顧心茫然。\n欲渡黃河冰塞川，\n將登太行雪暗天。\n閑來垂釣碧溪上，\n忽復乘舟夢日邊。\n行路難！\n行路難！\n多歧路，\n今安在？\n長風破浪會有時，\n直挂雲帆濟滄海。",
