      "标题": "行路難（三首之二）",
      "上句": "大道如青天",
      "下句": "大道如青天，\n我獨不得出。\n羞逐長安社中兒，\n赤雞白狗賭梨栗。\n彈劍作歌奏苦聲，\n曳裾王門不稱情。\n淮陰市井笑韓信，\n漢朝公卿忌賈生。\n君不見昔時燕家重郭隗，\n擁篲折節無嫌猜；\n劇辛樂毅感恩分，\n輸肝剖膽效英才。\n昭王白骨縈蔓草，\n誰人更掃黃金臺？\n行路難，\n歸去來！",
