      "上句": "有耳莫洗潁川水",
      "下句": "有耳莫洗潁川水，\n有口莫食首陽蕨。\n含光混世貴無名，\n何用孤高比雲月；\n吾觀自古賢達人，\n功成不退皆殞身。\n子胥既棄吳江上，\n屈原終投湘水濱；\n陸機雄才豈自保，\n李斯稅駕苦不早。\n華亭鶴唳詎可聞？\n上蔡蒼鷹何足道。\n君不見吳中張翰稱達生，\n秋風忽憶江東行。\n且樂生前一杯酒，\n何須身後千載名？",
      "原文": "",
