      "原文": "君不見黃河之水天上來，\n奔流到海不復回；\n君不見高堂明鏡悲白髮，\n朝如青絲暮成雪。\n人生得意須盡歡，\n莫使金樽空對月。\n天生我材必有用，\n千金散盡還復來。\n烹羊宰牛且為樂，\n會須一飲三百杯。\n岑夫子，\n丹丘生，\n將進酒，\n君莫停。\n與君歌一曲，\n請君為我側耳聽：\n鐘鼓饌玉不足貴，\n但願長醉不願醒。\n古來聖賢皆寂寞，\n惟有飲者留其名。\n陳王昔時宴平樂，\n斗酒十千恣讙謔。\n主人何為言少錢，\n徑須沽取對君酌。\n五花馬，\n千金裘，\n呼兒將出換美酒，\n與爾同消萬古愁！",
      "译文": "",
      "注释": "",
