      "原文": "車轔轔，\n馬蕭蕭，\n行人弓箭各在腰。\n耶孃妻子走相送，\n塵埃不見咸陽橋。\n牽衣頓足攔道哭，\n哭聲直上干雲霄。\n道旁過者問行人，\n行人但云點行頻。\n或從十五北防河，\n便至四十西營田。\n去時里正與裹頭，\n歸來頭白還戍邊。\n邊亭流血成海水，\n武皇開邊意未已。\n君不聞漢家山東二百州，\n千村萬落生荊杞？\n縱有健婦把鋤犁，\n禾生隴畝無東西。\n況復秦兵耐苦戰，\n被驅不異犬與雞。\n長者雖有問，\n役夫敢申恨？\n且如今年冬，\n未休關西卒。\n縣官急索租，\n租稅從何出？\n信知生男惡，\n反是生女好；\n生女猶得嫁比鄰，\n生男埋沒隨百草。\n君不見青海頭，\n古來白骨無人收？\n新鬼煩冤舊鬼哭，\n天陰雨濕聲啾啾。",
      "译文": "",
