      "原文": "三月三日天氣新，\n長安水邊多麗人。\n態濃意遠淑且真，\n肌理細膩骨肉勻。\n繡羅衣裳照暮春，\n蹙金孔雀銀麒麟。\n頭上何所有？\n翠微□葉垂鬢唇。\n背後何所見？\n珠壓腰衱穩稱身。\n就中雲幕椒房親，\n賜名大國虢與秦。\n紫駝之峰出翠釜，\n水精之盤行素鱗。\n犀箸饜飫久未下，\n鸞刀縷切空紛綸。\n黃門飛鞚不動塵，\n御廚絡繹送八珍。\n簫鼓哀吟感鬼神，\n賓從雜遝實要津。\n後來鞍馬何逡巡！\n當軒下馬入錦茵。\n楊花雪落覆白蘋，\n青鳥飛去銜紅巾。\n炙手可熱勢絕倫，\n慎莫近前丞相嗔。",
