      "原文": "少陵野老吞生哭，\n春日潛行曲江曲。\n江頭宮殿鎖千門，\n細柳新蒲為誰綠？\n憶昔霓旌下南苑，\n苑中景物生顏色。\n昭陽殿裡第一人，\n同輦隨君侍君側。\n輦前才人帶弓箭，\n白馬嚼齧黃金勒。\n翻身向天仰射雲，\n一箭正墜雙飛翼。\n明眸皓齒今何在？\n血污遊魂歸不得。\n清渭東流劍閣深，\n去住彼此無消息。\n人生有情淚沾臆，\n江水江花豈終極？\n黃昏胡騎塵滿城，\n欲往城南望城北。",
