      "上句": "",
      "下句": "",
      "原文": "夫子何為者？\n栖栖一代中。\n地猶鄹氏邑，\n宅即魯王宮。\n歎鳳嗟身否，\n傷麟怨道窮。\n今看兩楹奠，\n當與夢時同。",
      "译文": "",
