      "上句": "聞道黃龍戍",
      "下句": "聞道黃龍戍，\n頻年不解兵。\n可憐閨裡月，\n長在漢家營。\n少婦今春意，\n良人昨夜情。\n誰能將旗鼓，\n一為取龍城？",
