      "标题": "夜泊牛渚懷古",
      "上句": "",
      "下句": "",
      "原文": "牛渚西江夜，\n青天無片雲。\n登舟望秋月，\n空憶謝將軍。\n余亦能高詠，\n斯人不可聞。\n明朝挂帆去，\n楓葉落紛紛。",
