      "标题": "月夜",
      "上句": "今夜鄜州月",
      "下句": "今夜鄜州月，\n閨中只獨看。\n遙憐小兒女，\n未解憶長安。\n香霧雲鬟濕，\n清輝玉臂寒。\n何時倚虛幌，\n雙照淚痕乾。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
