      "标题": "春望",
      "上句": "",
      "下句": "",
      "原文": "國破山河在，\n城春草木深。\n感時花濺淚，\n恨別鳥驚心。\n烽火連三月，\n家書抵萬金。\n白頭搔更短，\n渾欲不勝簪。",
      "译文": "",
      "注释": "",
      "赏析": "春望而伤时，「國破山河在，城春草木深」写乱离之景，末「白頭搔更短」见忧愤之深。沉郁顿挫，一字千钧。",
