      "篇目": "唐诗三百首 · 五言律诗 · 杜甫 · 至德二載甫自京金光門出，問道歸鳳翔。乾元初從左拾遺移華州掾。與親故別，因出此門。有悲往事",
      "标题": "至德二載甫自京金光門出，問道歸鳳翔。乾元初從左拾遺移華州掾。與親故別，因出此門。有悲往事",
