    "fields": {
      "篇目": "唐诗三百首 · 五言律诗 · 杜甫 · 月夜憶舍弟",
      "标题": "月夜憶舍弟",
      "上句": "戍鼓斷人行",
      "下句": "戍鼓斷人行，\n秋邊一雁聲。\n露從今夜白，\n月是故鄉明。\n有弟皆分散，\n無家問死生。\n寄書長不達，\n況乃未休兵。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
