      "下句": "",
      "原文": "細草微風岸，\n危檣獨夜舟。\n星垂平野闊，\n月湧大江流。\n名豈文章著，\n官應老病休。\n飄飄何所似，\n天地一沙鷗。",
      "译文": "",
