      "下句": "",
      "原文": "昔聞洞庭水，\n今上岳陽樓。\n吳楚東南坼，\n乾坤日夜浮。\n親朋無一字，\n老病有孤舟。\n戎馬關山北，\n憑軒涕泗流。",
      "译文": "",
