      "上句": "晚年惟好靜",
      "下句": "晚年惟好靜，\n萬事不關心。\n自顧無長策，\n空知返舊林。\n松風吹解帶，\n山月照彈琴。\n君問窮通理，\n漁歌入浦深。",
