      "标题": "終南別業",
      "上句": "",
      "下句": "",
      "原文": "中歲頗好道，\n晚家南山陲。\n興來美獨往，\n勝事空自知。\n行到水窮處，\n坐看雲起時。\n偶然值林叟，\n談笑無還期。",
