      "上句": "八月湖水平",
      "下句": "八月湖水平，\n涵虛混太清。\n氣蒸雲夢澤，\n波撼岳陽城。\n欲濟無舟楫，\n端居恥聖明。\n坐觀垂釣者，\n空有羨魚情。",
