      "标题": "臨洞庭上張丞相",
      "上句": "",
      "下句": "",
      "原文": "八月湖水平，\n涵虛混太清。\n氣蒸雲夢澤，\n波撼岳陽城。\n欲濟無舟楫，\n端居恥聖明。\n坐觀垂釣者，\n空有羨魚情。",
      "译文": "",
      "注释": "",
      "赏析": "临洞庭而寄望张丞相，「氣蒸雲夢澤，波撼岳陽城」写洞庭之壮，末「端居恥聖明」见干谒之意。雄浑得体。",
