      "标题": "與諸子登峴山",
      "上句": "人事有代謝",
      "下句": "人事有代謝，\n往來成古今。\n江山留勝跡，\n我輩復登臨。\n水落魚梁淺，\n天寒夢澤深。\n羊公碑字在，\n讀罷淚沾襟。",
