      "标题": "歲暮歸南山",
      "上句": "",
      "下句": "",
      "原文": "北闕休上書，\n南山歸敝廬。\n不才明主棄，\n多病故人疏。\n白髮催年老，\n青陽逼歲除。\n永懷愁不寐，\n松月夜窗虛。",
