      "标题": "過故人莊",
      "上句": "",
      "下句": "",
      "原文": "故人具雞黍，\n邀我至田家。\n綠樹村邊合，\n青山郭外斜。\n開軒面場圃，\n把酒話桑麻。\n待到重陽日，\n還來就菊花。",
