      "上句": "",
      "下句": "",
      "原文": "一丘嘗欲臥，\n三徑苦無資。\n北土非吾願，\n東林懷我師。\n黃金燃桂盡，\n壯志逐年衰。\n日夕涼風至，\n聞蟬但益悲。",
