      "上句": "山暝聽猿愁",
      "下句": "山暝聽猿愁，\n滄江急夜流。\n風鳴兩岸葉，\n月照一孤舟。\n建德非吾土，\n維揚憶舊遊。\n還將兩行淚，\n遙寄海西頭。",
      "原文": "",
