    "fields": {
      "篇目": "唐诗三百首 · 五言律诗 · 韋應物 · 淮上喜會梁川故人",
      "标题": "淮上喜會梁川故人",
      "上句": "",
      "下句": "",
      "原文": "江漢曾為客，\n相逢每醉還。\n浮雲一別後，\n流水十年間。\n歡笑情如舊，\n蕭疏鬢已斑。\n何因不歸去？\n淮上對秋山。",
      "译文": "",
      "注释": "",
      "赏析": "淮上喜会故人，「江漢曾為客」写旧游之忆，末「何因不歸去」见漂泊之感。疏淡真挚。",
      "链接": ""
    },
