      "下句": "",
      "原文": "離離原上草，\n一歲一枯榮。\n野火燒不盡，\n春風吹又生。\n遠芳侵古道，\n晴翠接荒城。\n又送王孫去，\n萋萋滿別情。",
      "译文": "",
