      "上句": "旅館無良伴",
      "下句": "旅館無良伴，\n凝情自悄然。\n寒燈思舊事，\n斷雁警愁眠。\n遠夢歸侵曉，\n家書到隔年。\n滄江好煙月，\n門繫釣魚船。",
      "原文": "",
