      "上句": "遙夜汎清瑟",
      "下句": "遙夜汎清瑟，\n西風生翠蘿。\n殘螢栖玉露，\n早雁拂銀河。\n高樹曉還密，\n遠山晴更多。\n淮南一葉下，\n自覺老煙波。",
