      "上句": "本以高難飽",
      "下句": "本以高難飽，\n徒勞恨費聲。\n五更疏欲斷，\n一樹碧無情。\n薄宦梗猶汎，\n故園蕪已平。\n煩君最相警，\n我亦舉家清。",
      "原文": "",
