      "标题": "黃鶴樓",
      "上句": "",
      "下句": "",
      "原文": "昔人已乘黃鶴去，\n此地空餘黃鶴樓。\n黃鶴一去不復返，\n白雲千載空悠悠。\n晴川歷歷漢陽樹，\n芳草萋萋鸚鵡洲。\n日暮鄉關何處是？\n煙波江上使人愁。",
      "译文": "",
      "注释": "",
      "赏析": "黄鹤楼，「昔人已乘黃鶴去」写登楼之慨，末「煙波江上使人愁」见乡愁之深。气象浑成，为咏楼绝唱。",
      "链接": ""
