      "上句": "燕臺一去客心驚",
      "下句": "燕臺一去客心驚，\n簫鼓喧喧漢將營。\n萬里寒光生積雪，\n三邊曙色動危旌。\n沙場烽火侵胡月，\n海畔雲山擁薊城。\n少小雖非投筆吏，\n論功還欲請長纓。",
      "原文": "",
