      "上句": "朝聞遊子唱驪歌",
      "下句": "朝聞遊子唱驪歌，\n昨夜微霜初度河。\n鴻雁不堪愁裡聽，\n雲山況是客中過。\n關城樹色催寒近，\n御苑砧聲向晚多。\n莫見長安行樂處，\n空令歲月易蹉跎。",
