      "上句": "鳳凰臺上鳳凰遊",
      "下句": "鳳凰臺上鳳凰遊，\n鳳去臺空江自流。\n吳宮花草埋幽徑，\n晉代衣冠成古邱。\n三山半落青山外，\n二水中分白鷺洲。\n總為浮雲能蔽日，\n長安不見使人愁。",
