      "上句": "積雨空林煙火遲",
      "下句": "積雨空林煙火遲，\n蒸藜炊黍餉東菑。\n漠漠水田飛白鷺，\n陰陰夏木囀黃鸝。\n山中習靜觀朝槿，\n松下清齋折露葵。\n野老與人爭席罷，\n海鷗何事更相疑？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
