      "标题": "酬郭給事",
      "上句": "洞門高閣靄餘輝",
      "下句": "洞門高閣靄餘輝，\n桃李陰陰柳絮飛。\n禁裡疏鐘官舍晚，\n省中啼鳥吏人稀。\n晨搖玉珮趨金殿，\n夕奉天書拜瑣闈。\n強欲從君無那老，\n將因臥病解朝衣。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
