      "标题": "蜀相",
      "上句": "丞相祠堂何處尋",
      "下句": "丞相祠堂何處尋？\n錦官城外柏森森。\n映階碧草自春色，\n隔葉黃鸝空好音。\n三顧頻煩天下計，\n兩朝開濟老臣心。\n出師未捷身先死，\n長使英雄淚滿襟。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
