      "标题": "蜀相",
      "上句": "",
      "下句": "",
      "原文": "丞相祠堂何處尋？\n錦官城外柏森森。\n映階碧草自春色，\n隔葉黃鸝空好音。\n三顧頻煩天下計，\n兩朝開濟老臣心。\n出師未捷身先死，\n長使英雄淚滿襟。",
      "译文": "",
      "注释": "",
      "赏析": "蜀相，「丞相祠堂何處尋」写谒祠之诚，末「出師未捷身先死」见叹惋之深。沉郁顿挫，为咏诸葛亮绝唱。",
      "链接": ""
