      "标题": "客至",
      "上句": "舍南舍北皆春水",
      "下句": "舍南舍北皆春水，\n但見群鷗日日來。\n花徑不曾緣客掃，\n蓬門今始為君開。\n盤飧市遠無兼味，\n樽酒家貧只舊醅。\n肯與鄰翁相對飲，\n隔籬呼取盡餘杯。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
