      "原文": "西山白雪三城戍，\n南浦清江萬里橋。\n海內風塵諸弟隔，\n天涯涕淚一身遙。\n唯將遲暮供多病，\n未有涓埃答聖朝。\n跨馬出郊時極目，\n不堪人事日蕭條。",
