      "篇目": "唐诗三百首 · 七言律诗 · 杜甫 · 聞官軍收河南河北",
      "标题": "聞官軍收河南河北",
      "上句": "劍外忽傳收薊北",
      "下句": "劍外忽傳收薊北，\n初聞涕淚滿衣裳。\n卻看妻子愁何在，\n漫卷詩書喜欲狂。\n白日放歌須縱酒，\n青春作伴好還鄉。\n即從巴峽穿巫峽，\n便下襄陽向洛陽。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
