      "下句": "",
      "原文": "風急天高猿嘯哀，\n渚清沙白鳥飛迴。\n無邊落木蕭蕭下，\n不盡長江滾滾來。\n萬里悲秋常作客，\n百年多病獨登臺。\n艱難苦恨繁霜鬢，\n潦倒新停濁酒杯。",
      "译文": "",
      "注释": "",
      "赏析": "登高，「風急天高猿嘯哀」写秋景之悲，末「潦倒新停濁酒杯」见身世之叹。沉郁顿挫，为七律绝唱。",
