      "上句": "花近高樓傷客心",
      "下句": "花近高樓傷客心，\n萬方多難此登臨。\n錦江春色來天地，\n玉壘浮雲變古今。\n北極朝庭終不改，\n西山寇盜莫相侵。\n可憐後主還祠廟，\n日暮聊為梁父吟。",
