      "下句": "清秋幕府井梧寒，\n獨宿江城蠟炬殘。\n永夜角聲悲自語，\n中天月色好誰看？\n風塵荏苒音書絕，\n關塞蕭條行路難。\n已忍伶俜十年事，\n強移棲息一枝安。",
