      "下句": "歲暮陰陽催短景，\n天涯霜雪霽寒霄。\n五更鼓角聲悲壯，\n三峽星河影動搖。\n野哭千家聞戰伐，\n夷歌數處起漁樵。\n臥龍躍馬終黃土，\n人事音書漫寂寥。",
