      "上句": "去年花裡逢君別",
      "下句": "去年花裡逢君別，\n今日花開又一年。\n世事茫茫難自料，\n春愁黯黯獨成眠。\n身多疾病思田里，\n邑有流亡愧俸錢。\n聞道欲來相問訊，\n西樓望月幾回圓？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
