      "上句": "仙臺初見五城樓",
      "下句": "仙臺初見五城樓，\n風物淒淒宿雨收。\n山色遙連秦樹晚，\n砧聲近報漢宮秋。\n疏松影落空壇靜，\n細草香閑小洞幽。\n何用別尋方外去？\n人間亦自有丹丘。",
