      "下句": "雲開遠見漢陽城，\n猶是孤帆一日程。\n估客晝眠知浪靜，\n舟人夜語覺潮生。\n三湘愁鬢逢秋色，\n萬里歸心對月明。\n舊業已隨征戰盡，\n更堪江上鼓鼙聲！",
