      "上句": "謝公最小偏憐女",
      "下句": "謝公最小偏憐女，\n自嫁黔婁百事乖。\n顧我無衣搜藎篋，\n泥他沽酒拔金釵。\n野蔬充膳甘長藿，\n落葉添薪仰古槐。\n今日俸錢過十萬，\n與君營奠復營齋。",
