      "上句": "昔日戲言身後事",
      "下句": "昔日戲言身後事，\n今朝都到眼前來。\n衣裳已施行看盡，\n針線猶存未忍開。\n尚想舊情憐婢僕，\n也曾因夢送錢財。\n誠知此恨人人有，\n貧賤夫妻百事哀。",
