      "上句": "閑坐悲君亦自悲",
      "下句": "閑坐悲君亦自悲，\n百年都是幾多時。\n鄧攸無子尋知命，\n潘岳悼亡猶費詞。\n同穴窅冥何所望，\n他生緣會更難期。\n惟將終夜長開眼，\n報答平生未展眉。",
