      "原文": "錦瑟無端五十絃，\n一絃一柱思華年。\n莊生曉夢迷蝴蝶，\n望帝春心託杜鵑。\n滄海月明珠有淚，\n藍田日暖玉生煙。\n此情可待成追憶，\n只是當時已惘然。",
      "译文": "",
      "注释": "",
      "赏析": "锦瑟，「錦瑟無端五十絃」写华年之忆，末「此情可待成追憶」见惘然之叹。辞采华美，意蕴朦胧，为李商隐代表作。",
