      "原文": "昨夜星辰昨夜風，\n畫樓西畔桂堂東。\n身無綵鳳雙飛翼，\n心有靈犀一點通。\n隔座送鉤春酒暖，\n分曹射覆蠟燈紅。\n嗟余聽鼓應官去，\n走馬蘭臺類轉蓬。",
