    "fields": {
      "篇目": "唐诗三百首 · 七言律诗 · 李商隱 · 隋宮",
      "标题": "隋宮",
      "上句": "紫泉宮殿鎖煙霞",
      "下句": "紫泉宮殿鎖煙霞，\n欲取蕪城作帝家。\n玉璽不緣歸日角，\n錦帆應是到天涯。\n於今腐草無螢火，\n終古垂楊有暮鴉。\n地下若逢陳後主，\n豈宜重問後庭花？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
    },
