      "篇目": "唐诗三百首 · 七言律诗 · 李商隱 · 無題（二首之二）",
      "标题": "無題（二首之二）",
      "上句": "颯颯東風細雨來",
      "下句": "颯颯東風細雨來，\n芙蓉塘外有輕雷。\n金蟾齧璅燒香入，\n玉虎牽絲汲井迴。\n賈氏窺簾韓掾少，\n宓妃留枕魏王才。\n春心莫共花爭發，\n一寸相思一寸灰。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
