      "标题": "無題",
      "上句": "相見時難別亦難",
      "下句": "相見時難別亦難，\n東風無力百花殘。\n春蠶到死絲方盡，\n蠟炬成灰淚始乾。\n曉鏡但愁雲鬢改，\n夜吟應覺月光寒。\n蓬萊此去無多路，\n青鳥殷勤為探看。",
