      "上句": "悵臥新春白袷衣",
      "下句": "悵臥新春白袷衣，\n白門寥落意多違。\n紅樓隔雨相望冷，\n珠箔飄燈獨自歸。\n遠路應悲春晼晚，\n殘宵猶得夢依稀。\n玉璫緘札何由達，\n萬里雲羅一雁飛。",
