      "上句": "鳳尾香羅薄幾重",
      "下句": "鳳尾香羅薄幾重，\n碧文圓頂夜深縫。\n扇裁月魄羞難掩，\n車走雷聲語未通。\n曾是寂寥金燼暗，\n斷無消息石榴紅。\n斑騅只繫垂楊岸，\n何處西南任好風？",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
