      "标题": "無題（二首之二）",
      "上句": "重帷深下莫愁堂",
      "下句": "重帷深下莫愁堂，\n臥後清宵細細長。\n神女生涯原是夢，\n小姑居處本無郎。\n風波不信菱枝弱，\n月露誰教桂葉香？\n直道相思了無益，\n未妨惆悵是清狂。",
