      "上句": "澹然空水對斜暉",
      "下句": "澹然空水對斜暉，\n曲島蒼茫接翠微。\n波上馬嘶看棹去，\n柳邊人歇待船歸。\n數叢沙草群鷗散，\n萬頃江田一鷺飛。\n誰解乘舟尋范蠡？\n五湖煙水獨忘機。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
      "链接": ""
