      "原文": "蘇武魂銷漢使前，\n古祠高樹兩茫然。\n雲邊雁斷胡天月，\n隴上羊歸塞草煙。\n迴日樓臺非甲帳，\n去時冠劍是丁年。\n茂陵不見封侯印，\n空向秋波哭逝川。",
