      "下句": "",
      "原文": "十二樓中盡曉妝，\n望仙樓上望君王。\n鎖銜金獸連環冷，\n水滴銅龍晝漏長。\n雲髻罷梳還對鏡，\n羅衣欲換更添香。\n遙窺正殿簾開處，\n袍褲宮人掃御床。",
