      "上句": "蓬門未識綺羅香",
      "下句": "蓬門未識綺羅香，\n擬託良媒益自傷。\n誰愛風流高格調，\n共憐時世儉梳妝。\n敢將十指誇鍼巧，\n不把雙眉鬥畫長。\n苦恨年年壓金線，\n為他人作嫁衣裳。",
      "原文": "",
      "译文": "",
      "注释": "",
      "赏析": "",
