      "上句": "",
      "下句": "",
      "原文": "蓬門未識綺羅香，\n擬託良媒益自傷。\n誰愛風流高格調，\n共憐時世儉梳妝。\n敢將十指誇鍼巧，\n不把雙眉鬥畫長。\n苦恨年年壓金線，\n為他人作嫁衣裳。",
      "译文": "",
      "注释": "",
      "赏析": "贫女，「蓬門未識綺羅香」写贫女之叹，末「為他人作嫁衣裳」见不平之鸣。哀婉深挚。",
      "链接": ""
