      "标题": "獨不見",
      "上句": "",
      "下句": "",
      "原文": "盧家少婦鬱金香，\n海燕雙棲玳瑁梁。\n九月寒砧催木葉，\n十年征戍憶遼陽。\n白狼河北音書斷，\n丹鳳城南秋夜長。\n誰為含愁獨不見，\n更教明月照流黃。",
      "译文": "",
      "注释": "",
      "赏析": "独不见，「盧家少婦鬱金香」写思妇之怨，末「誰為含愁獨不見」见相思之苦。绮丽凄婉。",
      "链接": ""
