      "下句": "",
      "原文": "月落烏啼霜滿天，\n江楓漁火對愁眠。\n姑蘇城外寒山寺，\n夜半鐘聲到客船。",
      "译文": "",
      "注释": "",
      "赏析": "枫桥夜泊，「月落烏啼霜滿天，江楓漁火對愁眠」写夜泊之景，末「夜半鐘聲到客船」见客愁之深。意境幽远，千古名篇。",
      "链接": ""
