      "原文": "勸君莫惜金縷衣，\n勸君惜取少年時。\n花開堪折直須折，\n莫待無花空折枝。",
      "译文": "",
      "注释": "",
      "赏析": "金缕衣，「勸君莫惜金縷衣，勸君惜取少年時」写劝学惜时，末「莫待無花空折枝」见警醒之意。明白如话，千古传诵。",
      "链接": ""
